package com.tracker.service; import com.tracker.repository.UserRepository; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; @Service public class UserDetailsServiceImpl implements UserDetailsService { private final UserRepository repo; public UserDetailsServiceImpl(UserRepository r){repo=r;} public UserDetails loadUserByUsername(String e){var u=repo.findByEmailIgnoreCase(e).orElseThrow(()->new UsernameNotFoundException("Invalid email or password")); return User.withUsername(u.getEmail()).password(u.getPassword()).roles(u.getRole().name()).build();} }
